function HeightInput({label,value,min,max,step=50,onChange}:{label:string;value:number;min:number;max:number;step?:number;onChange:(value:number)=>void}){
 const[draft,setDraft]=useState(String(Math.round(value)));
 useEffect(()=>setDraft(String(Math.round(value))),[value]);
 const commit=()=>{if(!draft.trim()){setDraft(String(Math.round(value)));return}const parsed=Number(draft);if(!Number.isFinite(parsed)){setDraft(String(Math.round(value)));return}const next=Math.round(clamp(parsed,min,max));setDraft(String(next));if(next!==Math.round(value))onChange(next)};
 const nudge=(delta:number)=>{const next=Math.round(clamp(Math.round(value)+delta,min,max));setDraft(String(next));if(next!==Math.round(value))onChange(next)};
 return <div className="mountain-height-field"><span>{label}</span><div className="mountain-height-editor"><button type="button" onClick={()=>nudge(-step)} disabled={value<=min} aria-label={`${label} um ${step} Meter verringern`}>−</button><input type="text" inputMode="numeric" pattern="[0-9]*" value={draft} onFocus={event=>event.currentTarget.select()} onChange={event=>setDraft(event.target.value.replace(/[^0-9]/g,''))} onBlur={commit} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();event.currentTarget.blur()}else if(event.key==='Escape'){setDraft(String(Math.round(value)));event.currentTarget.blur()}}} aria-label={`${label} in Metern direkt eingeben`}/><button type="button" onClick={()=>nudge(step)} disabled={value>=max} aria-label={`${label} um ${step} Meter erhöhen`}>+</button></div><b>m</b></div>
}
