    <div className="search-input-shell" onTouchStartCapture={beginSearchTouch} onTouchEndCapture={endSearchTouch} onTouchCancelCapture={()=>{searchTouchRef.current=null}} onPointerDown={event=>{if(event.pointerType!=='mouse'||(event.target as HTMLElement).closest('button'))return;focusSearchInput()}} onClick={event=>{if((event.target as HTMLElement).closest('button'))return;focusSearchInput()}}><Search size={18}/><input ref={inputRef} type="search" inputMode="search" enterKeyHint="search" autoCapitalize="none" autoCorrect="off" spellCheck={false} value={q} onPointerDown={()=>setOpen(true)} onFocus={()=>setOpen(true)} onChange={event=>{setQ(event.target.value);setOpen(true)}} placeholder="Ort, PLZ, ICAO, POI oder Favorit suchen" aria-label="Ort, ICAO-Kennung oder Favorit suchen" aria-expanded={open}/>{(q||open)&&<button type="button" onMouseDown={event=>event.preventDefault()} onClick={()=>{if(q){setQ('');setResults([]);focusSearchInput()}else closeSearch()}} title={q?'Suche leeren':'Suche schließen'} aria-label={q?'Suche leeren':'Suche schließen'}><X size={16}/></button>}</div>
